package net.zartra.gui;
import java.io.File;import java.util.logging.Logger;import org.bukkit.Material;import org.bukkit.inventory.ItemStack;import org.junit.Test;import static org.junit.Assert.*;
public class Goal2MenuItemStorageTest {@Test public void advancedMenuAndItemFieldsRoundTrip()throws Exception{File dir=new File(System.getProperty("java.io.tmpdir"),"zgui-advanced-"+System.nanoTime());MenuStorage s=new MenuStorage(dir,Logger.getLogger("test"));MenuDefinition m=new MenuDefinition("advanced","Advanced",4);m.inventoryType="CHEST";m.playerInventoryInteraction=true;m.itemsTakeable=true;m.maximumViewers=3;m.defaultFillerMaterial="STAINED_GLASS_PANE";m.paginationContentSlots.add(10);m.paginationContentSlots.add(11);MenuItem i=new MenuItem(new ItemStack(Material.STONE),null);i.priority=5;i.fallbackMaterial="DIRT";i.hideEnchantments=true;i.unbreakable=true;i.customModelData=12;i.headOwner="Alex";i.leatherColor="255,0,0";i.potionData="SPEED:200:1";i.enchantments.put("DURABILITY",3);m.items.put(1,i);s.save(m);MenuDefinition r=s.load().get("advanced");assertTrue(r.playerInventoryInteraction);assertTrue(r.itemsTakeable);assertEquals(3,r.maximumViewers);assertEquals(2,r.paginationContentSlots.size());MenuItem ri=r.items.get(1);assertEquals(5,ri.priority);assertEquals("DIRT",ri.fallbackMaterial);assertEquals(12,ri.customModelData);assertEquals(Integer.valueOf(3),ri.enchantments.get("DURABILITY"));}}